/**
 * Simulate an ocean surface
 *
 * bpy.types.OceanModifier
 */
export interface OceanModifier extends R.Modifier {
  /**
   * Method of modifying geometry Default: 'GENERATE'.
   * - `GENERATE`: Generate (Generate ocean surface geometry at the specified resolution)
   * - `DISPLACE`: Displace (Displace existing geometry according to simulation)
   */
  get geometry_mode(): H.Ref<"GENERATE" | "DISPLACE">;
  set geometry_mode(v: H.In<"GENERATE" | "DISPLACE">);
  /** Surface scale factor (does not affect the height of the waves) Range: 0 to inf. Default: 1.0. */
  get size(): H.Ref<number>;
  set size(v: H.In<number>);
  /** Repetitions of the generated surface in X Range: 1 to 1024. Default: 1. */
  get repeat_x(): H.Ref<number>;
  set repeat_x(v: H.In<number>);
  /** Repetitions of the generated surface in Y Range: 1 to 1024. Default: 1. */
  get repeat_y(): H.Ref<number>;
  set repeat_y(v: H.In<number>);
  /** Output normals for bump mapping - disabling can speed up performance if it's not needed Default: False. */
  get use_normals(): H.Ref<boolean>;
  set use_normals(v: H.In<boolean>);
  /** Generate foam mask as a vertex color channel Default: False. */
  get use_foam(): H.Ref<boolean>;
  set use_foam(v: H.In<boolean>);
  /** Generate map of spray direction as a vertex color channel Default: False. */
  get use_spray(): H.Ref<boolean>;
  set use_spray(v: H.In<boolean>);
  /** Invert the spray direction map Default: False. */
  get invert_spray(): H.Ref<boolean>;
  set invert_spray(v: H.In<boolean>);
  /** Name of the vertex color layer used for the spray direction map Default: "". */
  get spray_layer_name(): H.Ref<string>;
  set spray_layer_name(v: H.In<string>);
  /** Resolution of the generated surface for rendering and baking Range: 1 to 1024. Default: 7. */
  get resolution(): H.Ref<number>;
  set resolution(v: H.In<number>);
  /** Viewport resolution of the generated surface Range: 1 to 1024. Default: 7. */
  get viewport_resolution(): H.Ref<number>;
  set viewport_resolution(v: H.In<number>);
  /** Size of the simulation domain (in meters), and of the generated geometry (in BU) Range: -2147483648 to 2147483647. Default: 50. */
  get spatial_size(): H.Ref<number>;
  set spatial_size(v: H.In<number>);
  /** Wind speed Default: 30.0. */
  get wind_velocity(): H.Ref<number>;
  set wind_velocity(v: H.In<number>);
  /** Damp reflected waves going in opposite direction to the wind Range: 0 to 1. Default: 0.5. */
  get damping(): H.Ref<number>;
  set damping(v: H.In<number>);
  /** Shortest allowed wavelength Range: 0 to inf. Default: 0.01. */
  get wave_scale_min(): H.Ref<number>;
  set wave_scale_min(v: H.In<number>);
  /** How much the waves are aligned to each other Range: 0 to 1. Default: 0.0. */
  get wave_alignment(): H.Ref<number>;
  set wave_alignment(v: H.In<number>);
  /** Main direction of the waves when they are (partially) aligned Default: 0.0. */
  get wave_direction(): H.Ref<number>;
  set wave_direction(v: H.In<number>);
  /** Scale of the displacement effect Range: 0 to inf. Default: 1.0. */
  get wave_scale(): H.Ref<number>;
  set wave_scale(v: H.In<number>);
  /** Depth of the solid ground below the water surface Default: 200.0. */
  get depth(): H.Ref<number>;
  set depth(v: H.In<number>);
  /** Amount of generated foam Default: 0.0. */
  get foam_coverage(): H.Ref<number>;
  set foam_coverage(v: H.In<number>);
  /** How much foam accumulates over time (baked ocean only) Range: 0 to inf. Default: 0.98. */
  get bake_foam_fade(): H.Ref<number>;
  set bake_foam_fade(v: H.In<number>);
  /** Name of the vertex color layer used for foam Default: "". */
  get foam_layer_name(): H.Ref<string>;
  set foam_layer_name(v: H.In<string>);
  /** Choppiness of the wave's crest (adds some horizontal component to the displacement) Range: 0 to inf. Default: 1.0. */
  get choppiness(): H.Ref<number>;
  set choppiness(v: H.In<number>);
  /** Current time of the simulation Range: 0 to inf. Default: 1.0. */
  get time(): H.Ref<number>;
  set time(v: H.In<number>);
  /**
   * Spectrum to use Default: 'PHILLIPS'.
   * - `PHILLIPS`: Turbulent Ocean (Use for turbulent seas with foam)
   * - `PIERSON_MOSKOWITZ`: Established Ocean (Use for a large area, established ocean (Pierson-Moskowitz method))
   * - `JONSWAP`: Established Ocean (Sharp Peaks) (Use for established oceans ('JONSWAP', Pierson-Moskowitz method) with peak sharpening)
   * - `TEXEL_MARSEN_ARSLOE`: Shallow Water (Use for shallow water ('JONSWAP', 'TMA' - Texel-Marsen-Arsloe method))
   */
  get spectrum(): H.Ref<"PHILLIPS" | "PIERSON_MOSKOWITZ" | "JONSWAP" | "TEXEL_MARSEN_ARSLOE">;
  set spectrum(v: H.In<"PHILLIPS" | "PIERSON_MOSKOWITZ" | "JONSWAP" | "TEXEL_MARSEN_ARSLOE">);
  /** This is the distance from a lee shore, called the fetch, or the distance over which the wind blows with constant velocity. Used by 'JONSWAP' and 'TMA' models. Range: 0 to inf. Default: 120.0. */
  get fetch_jonswap(): H.Ref<number>;
  set fetch_jonswap(v: H.In<number>);
  /** Peak sharpening for 'JONSWAP' and 'TMA' models Range: 0 to 1. Default: 0.0. */
  get sharpen_peak_jonswap(): H.Ref<number>;
  set sharpen_peak_jonswap(v: H.In<number>);
  /** Seed of the random generator Range: 0 to 2147483647. Default: 0. */
  get random_seed(): H.Ref<number>;
  set random_seed(v: H.In<number>);
  /** Start frame of the ocean baking Range: -2147483648 to 2147483647. Default: 1. */
  get frame_start(): H.Ref<number>;
  set frame_start(v: H.In<number>);
  /** End frame of the ocean baking Range: -2147483648 to 2147483647. Default: 250. */
  get frame_end(): H.Ref<number>;
  set frame_end(v: H.In<number>);
  /** Whether the ocean is using cached data or simulating Default: False. */
  get is_cached(): H.Ref<boolean>;
  /** Path to a folder to store external baked images Default: "". */
  get filepath(): H.Ref<string>;
  set filepath(v: H.In<string>);
}

/**
 * Storage of an operator being executed, or registered after execution
 *
 * bpy.types.Operator
 */
export interface Operator extends R.bpy_struct {
  /** Name Default: "". */
  get name(): H.Ref<string>;
  /** Properties */
  get properties(): H.Own<R.OperatorProperties>;
  /** Operator has a set of reports (warnings and errors) from last execution Default: False. */
  get has_reports(): H.Ref<boolean>;
  /** Default: "". */
  get bl_idname(): H.Ref<string>;
  set bl_idname(v: H.In<string>);
  /** Default: "". */
  get bl_label(): H.Ref<string>;
  set bl_label(v: H.In<string>);
  /** Default: "Operator". */
  get bl_translation_context(): H.Ref<string>;
  set bl_translation_context(v: H.In<string>);
  /** Default: "". */
  get bl_description(): H.Ref<string>;
  set bl_description(v: H.In<string>);
  /** Default: "". */
  get bl_undo_group(): H.Ref<string>;
  set bl_undo_group(v: H.In<string>);
  /** Options for this operator type Default: set(). */
  get bl_options(): H.Ref<Set<E.MacroBlOptions>>;
  set bl_options(v: H.In<Set<E.MacroBlOptions>>);
  /** Cursor to use when waiting for the user to select a location to activate the operator (when ``bl_options`` has ``DEPENDS_ON_CURSOR`` set) Default: 'DEFAULT'. */
  get bl_cursor_pending(): H.Ref<E.MacroBlCursorPending>;
  set bl_cursor_pending(v: H.In<E.MacroBlCursorPending>);
  get layout(): H.Ptr<R.UILayout>;
  /** Runtime options */
  get options(): H.Own<R.OperatorOptions>;
  /** Macros */
  readonly macros: H.Own<H.Coll<R.Macro>>;
  /** report */
  report(type: H.In<Set<E.MacroType>>, message: H.In<string>): H.Ref<void>;
  /** report */
  report(kw: { type: H.In<Set<E.MacroType>>; message: H.In<string> }): H.Ref<void>;
  /** is_repeat */
  is_repeat(): H.Ref<boolean>;
  /** Test if the operator can be called or not */
  poll(context: R.Context): H.Ref<boolean>;
  /** Test if the operator can be called or not */
  poll(kw: { context: R.Context }): H.Ref<boolean>;
  /** Execute the operator */
  execute(context: R.Context): H.Ref<Set<"RUNNING_MODAL" | "CANCELLED" | "FINISHED" | "PASS_THROUGH" | "INTERFACE">>;
  /** Execute the operator */
  execute(kw: { context: R.Context }): H.Ref<Set<"RUNNING_MODAL" | "CANCELLED" | "FINISHED" | "PASS_THROUGH" | "INTERFACE">>;
  /** Check the operator settings, return True to signal a change to redraw */
  check(context: R.Context): H.Ref<boolean>;
  /** Check the operator settings, return True to signal a change to redraw */
  check(kw: { context: R.Context }): H.Ref<boolean>;
  /** Invoke the operator */
  invoke(context: R.Context, event: R.Event): H.Ref<Set<"RUNNING_MODAL" | "CANCELLED" | "FINISHED" | "PASS_THROUGH" | "INTERFACE">>;
  /** Invoke the operator */
  invoke(kw: { context: R.Context; event: R.Event }): H.Ref<Set<"RUNNING_MODAL" | "CANCELLED" | "FINISHED" | "PASS_THROUGH" | "INTERFACE">>;
  /** Modal operator function */
  modal(context: R.Context, event: R.Event): H.Ref<Set<"RUNNING_MODAL" | "CANCELLED" | "FINISHED" | "PASS_THROUGH" | "INTERFACE">>;
  /** Modal operator function */
  modal(kw: { context: R.Context; event: R.Event }): H.Ref<Set<"RUNNING_MODAL" | "CANCELLED" | "FINISHED" | "PASS_THROUGH" | "INTERFACE">>;
  /** Draw function for the operator */
  draw(context: R.Context): H.Ref<void>;
  /** Draw function for the operator */
  draw(kw: { context: R.Context }): H.Ref<void>;
  /** Called when the operator is canceled */
  cancel(context: R.Context): H.Ref<void>;
  /** Called when the operator is canceled */
  cancel(kw: { context: R.Context }): H.Ref<void>;
  /** Compute a description string that depends on parameters */
  description(context: R.Context, properties: R.OperatorProperties): H.Ref<string>;
  /** Compute a description string that depends on parameters */
  description(kw: { context: R.Context; properties: R.OperatorProperties }): H.Ref<string>;
  /** @returns A copy of the properties as a dictionary. */
  as_keywords(kw?: {
    /** Property names to omit from the result. */
    ignore?: H.In<readonly string[]>;
  }): H.Ref<Map<string, any>>;
  /**
   * Set the message to show in the tool-tip when poll fails.
   *
   * When message is callable, additional user defined positional arguments are passed to the message function.
   * @param message The message or a function that returns the message.
   * @param args A sequence of arguments to pass to ``message``, if it's a callable, otherwise argument is not available.
   */
  poll_message_set(message: any, ...args: any[]): H.Ref<void>;
}

